from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from typing import Any


def _value(row: dict, key: str) -> Any:
    return row.get(key, "")


def _fixed(value: Any, width: int) -> str:
    text = "" if value is None else str(value)
    return text[:width].ljust(width)


def _is_empty(value: Any) -> bool:
    return value is None or value == ""


def _cents(value: Any) -> int:
    if _is_empty(value):
        return 0
    try:
        amount = Decimal(str(value))
    except (InvalidOperation, ValueError):
        amount = Decimal(0)
    return int((amount * Decimal("100")).quantize(
        Decimal("1"),
        rounding=ROUND_HALF_UP,
    ))


def _zpad(value: Any, width: int) -> str:
    cents = _cents(value)
    text = str(cents)
    if cents < 0:
        return "-" + text[1:].zfill(width - 1)
    return text.zfill(width)


def format_account(row: dict) -> str:
    account_id = _fixed(_value(row, "ACCT_ID"), 10)
    account_name = _fixed(_value(row, "ACCT_NM"), 40)
    region = _fixed(_value(row, "REGION_CD"), 3)
    annual_revenue = _zpad(_value(row, "ANN_REV"), 15)

    cred_hold_value = _value(row, "CRED_HOLD")
    cred_hold = "N" if _is_empty(cred_hold_value) else str(cred_hold_value)

    create_date_value = _value(row, "CREATE_DT")
    create_date = "00000000" if _is_empty(create_date_value) else str(create_date_value)

    return account_id + account_name + region + annual_revenue + cred_hold + create_date
